<?php
declare(strict_types=1); require_once __DIR__.'/../../config/ui.php'; require_login('ADMIN');
$month=(int)($_GET['mes']??date('n'));$year=(int)($_GET['ano']??date('Y'));$month=max(1,min(12,$month));$year=max(2020,min(2100,$year));$msg='';$err='';
if($_SERVER['REQUEST_METHOD']==='POST'){try{verify_csrf();$id=(int)($_POST['associado_id']??0);$value=(float)str_replace(',','.',str_replace('.','',$_POST['valor']??'0'));$ref=(int)$_POST['mes_referencia'];$refy=(int)$_POST['ano_referencia'];$status=$_POST['status_pagamento']??'PAGO';$date=$_POST['data_pagamento']?:null;if(!$id||$value<=0||!in_array($status,['PAGO','PENDENTE','CANCELADO'],true))throw new InvalidArgumentException('Informe dados válidos.');$q=$pdo->prepare('INSERT INTO mensalidades(associado_id,mes_referencia,ano_referencia,valor,data_vencimento,data_pagamento,forma_pagamento,status_pagamento,origem) VALUES(?,?,?,?,?,?,?,?,\'MANUAL\') ON DUPLICATE KEY UPDATE valor=VALUES(valor),data_pagamento=VALUES(data_pagamento),forma_pagamento=VALUES(forma_pagamento),status_pagamento=VALUES(status_pagamento)');$q->execute([$id,$ref,$refy,$value,$refy.'-'.str_pad((string)$ref,2,'0',STR_PAD_LEFT).'-10',$date,$_POST['forma_pagamento']??'Manual',$status]);if($status==='PAGO')$pdo->prepare("UPDATE usuarios SET status_financeiro='EM_DIA' WHERE id=? AND perfil='ASSOCIADO'")->execute([$id]);audit('LANCAMENTO_MENSALIDADE','mensalidades',$id);$msg='Lançamento guardado com sucesso.';}catch(Throwable $e){$err=$e instanceof InvalidArgumentException?$e->getMessage():'Não foi possível guardar o lançamento.';}}
$users=$pdo->query("SELECT id,nome,matricula FROM usuarios WHERE perfil='ASSOCIADO' ORDER BY nome")->fetchAll();$stats=$pdo->prepare("SELECT COUNT(*) total,COALESCE(SUM(valor),0) total_valor,COALESCE(SUM(status_pagamento='PAGO'),0) pagos FROM mensalidades WHERE mes_referencia=? AND ano_referencia=?");$stats->execute([$month,$year]);$s=$stats->fetch();$payments=$pdo->prepare("SELECT m.*,u.nome,u.matricula FROM mensalidades m JOIN usuarios u ON u.id=m.associado_id WHERE m.mes_referencia=? AND m.ano_referencia=? ORDER BY m.id DESC");$payments->execute([$month,$year]);admin_start('Financeiro','financeiro.php');?><div class="mb-8 flex flex-col justify-between gap-4 md:flex-row md:items-end"><div><p class="mb-2 text-sm font-semibold text-emerald-400">Nexus Financial</p><h2 class="text-3xl font-extrabold">Financeiro executivo</h2><p class="mt-2 text-sm text-slate-500">Controle de receitas, mensalidades e inadimplência.</p></div><a href="<?=e(app_url('admin/importar_retorno.php'))?>" class="rounded-lg bg-emerald-500 px-5 py-3 text-sm font-bold text-white">↥ Importar retorno</a></div><?php if($msg):?><div class="mb-5 rounded-lg bg-emerald-50 p-4 text-sm text-emerald-700"><?=e($msg)?></div><?php endif;?><?php if($err):?><div class="mb-5 rounded-lg bg-red-50 p-4 text-sm text-red-700"><?=e($err)?></div><?php endif;?><div class="mb-6 grid gap-5 md:grid-cols-3"><div class="rounded-xl bg-slate-900 p-6 text-white"><p class="text-sm text-slate-400">Receita registrada</p><b class="mt-3 block text-3xl text-emerald-400">R$ <?=e(number_format((float)$s['total_valor'],2,',','.'))?></b></div><div class="rounded-xl bg-slate-900 p-6 text-white"><p class="text-sm text-slate-400">Títulos no período</p><b class="mt-3 block text-3xl"><?=e($s['total'])?></b></div><div class="rounded-xl bg-slate-900 p-6 text-white"><p class="text-sm text-slate-400">Liquidados</p><b class="mt-3 block text-3xl text-blue-400"><?=e($s['pagos'])?></b></div></div><div class="grid gap-6 xl:grid-cols-3"><section class="shadow-soft rounded-xl border border-slate-100 bg-white p-6 xl:col-span-1"><h3 class="font-bold">Lançar mensalidade</h3><p class="mt-1 text-xs text-slate-400">Registre um pagamento manual.</p><form method="post" class="mt-5 space-y-4"><?=csrf_field()?><label class="block text-sm font-semibold">Associado<select name="associado_id" required class="mt-2 w-full rounded-lg border border-slate-200 px-3 py-3 text-sm"><?php foreach($users as $u):?><option value="<?=$u['id']?>"><?=e($u['nome'].' · '.$u['matricula'])?></option><?php endforeach;?></select></label><div class="grid grid-cols-2 gap-3"><label class="text-sm font-semibold">Mês<input name="mes_referencia" type="number" min="1" max="12" value="<?=$month?>" class="mt-2 w-full rounded-lg border border-slate-200 px-3 py-3"></label><label class="text-sm font-semibold">Ano<input name="ano_referencia" type="number" value="<?=$year?>" class="mt-2 w-full rounded-lg border border-slate-200 px-3 py-3"></label></div><label class="block text-sm font-semibold">Valor<input name="valor" required placeholder="150,00" class="mt-2 w-full rounded-lg border border-slate-200 px-3 py-3"></label><label class="block text-sm font-semibold">Forma<select name="forma_pagamento" class="mt-2 w-full rounded-lg border border-slate-200 px-3 py-3"><option>Pix</option><option>Boleto</option><option>Transferência</option><option>Dinheiro</option></select></label><button class="w-full rounded-lg bg-blue-600 py-3 text-sm font-bold text-white">Guardar lançamento</button></form></section><section class="shadow-soft rounded-xl border border-slate-100 bg-white p-6 xl:col-span-2"><div class="mb-5 flex justify-between"><div><h3 class="font-bold">Extrato de mensalidades</h3><p class="mt-1 text-xs text-slate-400">Referência <?=sprintf('%02d/%04d',$month,$year)?></p></div></div><div class="overflow-x-auto"><table class="w-full text-left text-sm"><thead class="border-b border-slate-100 text-xs uppercase text-slate-400"><tr><th class="pb-3">Associado</th><th class="pb-3">Método</th><th class="pb-3">Valor</th><th class="pb-3">Status</th></tr></thead><tbody><?php foreach($payments as $p):$paid=$p['status_pagamento']==='PAGO';?><tr class="border-b border-slate-50"><td class="py-4 font-semibold"><?=e($p['nome'])?><small class="block text-xs text-slate-400"><?=e($p['matricula'])?></small></td><td class="py-4 text-slate-500"><?=e($p['forma_pagamento']??'—')?></td><td class="py-4 font-bold">R$ <?=e(number_format((float)$p['valor'],2,',','.'))?></td><td class="py-4"><span class="rounded-full px-3 py-1 text-xs font-bold <?=$paid?'bg-emerald-50 text-emerald-700':'bg-amber-50 text-amber-700'?>"><?=e($paid?'PAGO':'PENDENTE')?></span></td></tr><?php endforeach;?></tbody></table></div></section></div><?php admin_end();